const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/capital_planning/settings',
  headers: {'Procore-Company-Id': 'SOME_STRING_VALUE'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/capital_planning/settings"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_STRING_VALUE" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/capital_planning/settings',
  headers: {'Procore-Company-Id': 'SOME_STRING_VALUE', 'content-type': 'application/json'},
  body: {fiscal_year_start: 'october'},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/capital_planning/settings"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_STRING_VALUE" },
    },
    Content = new StringContent("{\"fiscal_year_start\":\"october\"}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
